// fond de table : plateau de taverne en bois (image fournie par l'utilisateur, retravaillée)
const BOARD_IMG = 'data:image/jpeg;base64,';
try { document.documentElement.style.setProperty('--board-img', 'url(' + BOARD_IMG + ')'); } catch (e) {}

// plateau de l'univers Naruto : statue de la Vallée de la Fin (image fournie par l'utilisateur, bande noire retirée)
const BOARD_NJ = 'data:image/jpeg;base64,';
try { document.documentElement.style.setProperty('--board-nj', 'url(' + BOARD_NJ + ')'); } catch (e) {}

